#include <stdio.h>
#include <string.h>

#define MAXS 205

int S, T, P;
int A[MAXS];
int adj[MAXS][MAXS];
int deg[MAXS];
int memo[MAXS];

int dfs(int u) {
    if (memo[u] != -1) {
        return memo[u];
    }

    int max_dist = 0;
    for (int i = 0; i < deg[u]; i++) {
        int v = adj[u][i];
        int dist = 1 + dfs(v);
        if (dist > max_dist) {
            max_dist = dist;
        }
    }

    return memo[u] = max_dist;
}

int main() {
    if (scanf("%d %d %d", &S, &T, &P) != 3) {
        return 0;
    }

    for (int i = 1; i <= S; i++) {
        scanf("%d", &A[i]);
        deg[i] = 0;
        memo[i] = -1;
    }

    for (int k = 0; k < T; k++) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (A[u] > A[v]) {
            adj[u][deg[u]++] = v;
        } else if (A[v] > A[u]) {
            adj[v][deg[v]++] = u;
        }
    }

    printf("%d\n", dfs(P));

    return 0;
}
